using DigiTalent.Application.Common.Interfaces;
using DigiTalent.Application.UseCases.Platform.References;
using DigiTalent.Domain.Constants;
using Microsoft.EntityFrameworkCore;

namespace DigiTalent.Application.UseCases.Competency.Common;

internal sealed record PositionTargets(bool UsesSystemReference, IReadOnlyDictionary<Guid, int> Levels);

internal sealed class PositionTargetsReader(IApplicationDbContext context)
{
    // Versions generated by the old seeder used an unmarked, sparse TT02 matrix.
    private static readonly Dictionary<string, string> LegacySeedLevels = new()
    {
        ["CEO"] = "233332333202033220333333",
        ["HR"] = "222322332211023311223221",
        ["MARKETING"] = "332330333333222101232333",
        ["SALES_CRM"] = "223330332210023101221221",
        ["ACCOUNTANT"] = "233223212100223101221122",
    };

    private static readonly string[] CompetencyCodes =
    [
        "1.1", "1.2", "1.3", "2.1", "2.2", "2.3", "2.4", "2.5", "2.6",
        "3.1", "3.2", "3.3", "3.4", "4.1", "4.2", "4.3", "4.4",
        "5.1", "5.2", "5.3", "5.4", "6.1", "6.2", "6.3",
    ];

    public async Task<Dictionary<Guid, PositionTargets>> LoadAsync(Guid organizationId, IReadOnlyCollection<Guid> positionIds)
    {
        if (positionIds.Count == 0)
            return new();

        var positions = await context.JobPositions.AsNoTracking()
            .Where(p => p.OrganizationId == organizationId && positionIds.Contains(p.Id))
            .Select(p => new { p.Id, p.Code, p.Name }).ToListAsync();
        var categories = await context.CompetencyCategories.AsNoTracking()
            .Where(c => c.OrganizationId == organizationId && c.Status == Statuses.MasterData.Active)
            .Select(c => new { c.Id, c.Code }).ToListAsync();
        var sets = await context.PositionRequirementSets.AsNoTracking()
            .Where(s => positionIds.Contains(s.JobPositionId) && s.Status == Statuses.PositionRequirementSet.Active)
            .ToDictionaryAsync(s => s.JobPositionId);
        var setIds = sets.Values.Select(s => s.Id).ToArray();
        var items = (await (
                from item in context.PositionRequirementItems.AsNoTracking()
                join competency in context.Competencies.AsNoTracking() on item.CompetencyId equals competency.Id
                where setIds.Contains(item.RequirementSetId)
                select new { item.RequirementSetId, item.RequiredLevel, item.Note, competency.CategoryId, competency.Code })
            .ToListAsync()).ToLookup(item => item.RequirementSetId);
        ReferencePositionMatrix? matrix = null;
        var result = new Dictionary<Guid, PositionTargets>();
        foreach (var position in positions)
        {
            var set = sets.GetValueOrDefault(position.Id);
            var code = ReferencePositionMatrixService.MatchPosition(position.Code, position.Name);
            if (code != null && (set == null
                || (items[set.Id].Any() && items[set.Id].All(i => i.Note == ReferencePositionMatrixService.SeedItemNote))
                || (set.VersionNo == 1 && set.ActivatedAt is { } activated
                    && set.EffectiveFrom == DateOnly.FromDateTime(activated.UtcDateTime)
                    && items[set.Id].All(i => i.Note == null)
                    && IsLegacySeed(code, items[set.Id].Select(i => (i.Code, (int)i.RequiredLevel))))))
            {
                matrix ??= await ReferencePositionMatrixService.ReadAsync(context);
                var levels = matrix.Levels[code];
                result[position.Id] = new(true, categories
                    .Select(c => (c.Id, Number: DomainIndex(c.Code)))
                    .Where(c => c.Number >= 0)
                    .ToDictionary(c => c.Id, c => levels[c.Number]));
            }
            else if (set != null)
            {
                result[position.Id] = new(false, items[set.Id].Where(i => i.RequiredLevel > 0)
                    .GroupBy(i => i.CategoryId).ToDictionary(g => g.Key, g => (int)g.Max(i => i.RequiredLevel)));
            }
        }
        return result;
    }

    private static int DomainIndex(string code) =>
        code.Length == 7 && code.StartsWith("TT02_D", StringComparison.Ordinal) && code[6] is >= '1' and <= '6'
            ? code[6] - '1' : -1;

    private static bool IsLegacySeed(string code, IEnumerable<(string Code, int Level)> items)
    {
        var expected = LegacySeedLevels[code];
        var actual = items.ToList();
        return actual.Count == expected.Count(level => level != '0')
            && actual.All(item =>
            {
                var index = Array.IndexOf(CompetencyCodes, item.Code.StartsWith("TT02-") ? item.Code[5..] : item.Code);
                return index >= 0 && item.Level == expected[index] - '0';
            });
    }
}
